'use strict';
const $=s=>document.querySelector(s);
const state={i:Math.max(0,(parseInt(location.hash.slice(1))||1)-1),a:1,b:1,c:0,fault:0,step:0,quiz:0,answers:{},bits:12};
Object.assign(state,{motion:!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches,reveal:0,scanning:false,runAt:0});
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const eyebrow=s=>`<span class="eyebrow">${s}</span>`;
const title=(tag,h,sub='')=>`<div class="slide-title">${eyebrow(tag)}<h2>${h}</h2>${sub?`<p class="subtitle">${sub}</p>`:''}</div>`;
const layout=(a,b,cls='')=>`<div class="layout ${cls}"><div>${a}</div><div>${b}</div></div>`;
const row=(n,h,p)=>`<div class="row"><span class="number">${n}</span><div><h3>${h}</h3><p>${p}</p></div></div>`;
const term=(name,body)=>`<div class="terminal"><div class="terminal-title"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span>${name}</span></div><div class="terminal-body">${body}</div></div>`;
const formula=(label,f)=>`<div><span class="formula-label">${label}</span><div class="formula">${f}</div></div>`;
const buttons=(names=['A','B','C'])=>`<div class="interactive-label">CLICK AN INPUT TO TOGGLE ITS VALUE</div><div class="switches">${names.map(n=>`<button class="bit ${state[n.toLowerCase()]?'on':''}" data-bit="${n.toLowerCase()}" aria-label="Toggle input ${n}" aria-pressed="${!!state[n.toLowerCase()]}"><small>${n}</small>${state[n.toLowerCase()]}</button>`).join('')}</div>`;
const calc=(a,b,c,fault)=>{const w=a&b;const good=(w&c)|((1-w)&b),fw=fault;const bad=(fw&c)|((1-fw)&b);return{w,good,bad,detect:good^bad,obs:b^c};};
const readout=(good,bad,detect)=>`<div class="readout"><div><small>FAULT-FREE F</small><b>${good}</b></div><div><small>FAULTY F</small><b>${bad}</b></div><div><small>OUTPUT XOR</small><b class="${detect?'detected':'blocked'}">${detect}</b></div></div><p class="micro ${detect?'detected':'blocked'}">${detect?'DETECTED / Outputs disagree':'NOT DETECTED / Outputs agree'}</p>`;
const svg=(body,view='0 0 600 340')=>`<svg class="diagram" viewBox="${view}" role="img" aria-label="${body.includes('BDD_MARK')?'Binary decision diagram for A B NOT C':'Digital circuit diagram'}">${body}</svg>`;
const packet=(path,begin='0s')=>`<circle class="signal-packet" r="4.5"><animateMotion dur="2.4s" begin="${begin}" repeatCount="indefinite" path="${path}"/></circle>`;
function circuit(){const {a,b,c,fault}=state;const r=calc(a,b,c,fault);return svg(`
 <path class="wire" d="M25 125H95 M25 175H95 M25 40H385 M25 285H350 M270 150H305V80H385 M305 150V240H350 M470 70H490V140H526 M430 260H490V180H520 M580 160H595"/>
 <path class="${r.w?'live':'wire'}" d="M195 150H305"/><circle cx="305" cy="150" r="4" fill="var(--green)"/>
 <path class="gate" d="M95 105H145A45 45 0 0 1 145 195H95Z"/><text x="114" y="156">AND</text>
 <path class="gate" d="M385 20H420A50 50 0 0 1 420 120H385Z"/><text x="400" y="75">AND</text>
 <path class="gate" d="M350 220H390A40 40 0 0 1 390 300H350Z"/><text x="363" y="266">AND</text>
 <path class="gate" d="M520 125Q552 125 580 160Q552 195 520 195Q538 160 520 125Z"/>
 <circle class="node" cx="329" cy="240" r="7"/><path class="wire" d="M305 240H322 M336 240H350"/>
 <text x="24" y="112">A=${a}</text><text x="24" y="163">B=${b}</text><text x="24" y="27">C=${c}</text><text x="25" y="273">B=${b}</text>
 <text x="210" y="130" fill="var(--green)">w=${r.w}</text><text class="small-label" x="208" y="178">fault: s-a-${fault}</text><text x="572" y="143">F</text>
 <text class="small-label" x="370" y="327">F = wC + w′B</text>
 ${a?packet('M25 125H95'):''}${b?packet('M25 175H95','.2s'):''}${c?packet('M25 40H385','.4s'):''}${r.w?packet('M195 150H305V80H385','.5s'):''}${r.good?packet('M580 160H595','1s'):''}
 `);}
function bdd(){const {a,b,c}=state;const bOn=a===1,cOn=bOn&&b===1,win=cOn&&c===0;return svg(`<!-- BDD_MARK -->
 <path class="branch low ${!a?'active-path':''}" d="M290 55L110 285"/><path class="branch ${a?'active-path':''}" d="M305 65V120"/>
 <path class="branch low ${bOn&&!b?'active-path':''}" d="M287 150L110 285"/><path class="branch ${cOn?'active-path':''}" d="M305 160V215"/>
 <path class="branch ${cOn&&c?'active-path':''}" d="M285 245L110 285"/><path class="branch low ${win?'active-path':''}" d="M325 245L485 285"/>
 <circle class="node ${a?'hot':''}" cx="305" cy="42" r="25"/><text x="299" y="48">A</text>
 <circle class="node ${bOn?'hot':''}" cx="305" cy="137" r="25"/><text x="299" y="143">B</text>
 <circle class="node ${cOn?'hot':''}" cx="305" cy="232" r="25"/><text x="299" y="238">C</text>
 <rect class="terminal-node ${!win?'hot':''}" x="70" y="282" width="70" height="48"/><text x="99" y="313">0</text>
 <rect class="terminal-node ${win?'hot':''}" x="460" y="282" width="70" height="48"/><text x="489" y="313">1</text>
 <circle class="bdd-runner" r="7"><animateMotion dur="2.4s" repeatCount="indefinite" path="${!a?'M305 42L110 306':!b?'M305 42V137L110 306':c?'M305 42V232L110 306':'M305 42V232L495 306'}"/></circle>
 <text class="small-label" x="320" y="95">1</text><text class="small-label" x="205" y="141">0</text><text class="small-label" x="320" y="195">1</text><text class="small-label" x="205" y="230">0</text><text class="small-label" x="400" y="266">0</text><text class="small-label" x="205" y="285">1</text>
 `);}
const steps=[['Controllability','Build the switching function at the fault site. Activation requires the opposite of the stuck value.','CC(g) = g(X, S)'],['Observability','Compute the Boolean difference. It marks the inputs for which a change at g changes an output.','CO(g) = F|g=0 ⊕ F|g=1'],['Test diagram','AND activation with observability. Keep fanout stems explicit for now.','T₀(X, S) = CC(g) · CO(g)'],['Stem composition','Replace stem variables by their defining functions. Expand only the paths needed to obtain a test.','sᵢ ← sᵢ(X, s₁, …, sᵢ₋₁)'],['Test or redundancy','A surviving path to 1 gives a primary-input test cube. If the fully resolved test function is 0, the fault is redundant.','T(X) ≠ 0  /  T(X) ≡ 0']];
const questions=[{q:'A line g is stuck-at-1. Which condition activates the fault?',opts:['g = 1 in the good circuit','g = 0 in the good circuit','Any input with output F = 1'],correct:1,why:'Activation drives the good line to the opposite of its stuck value: g = 0.'},{q:'The primary-input test BDD reduces to terminal 0. What does that prove?',opts:['The circuit has no physical defects','The chosen variable order is invalid','The target fault is redundant'],correct:2,why:'No primary-input assignment makes T = 1. The target fault is untestable under the modeled conditions.'},{q:'For w = AB and F = wC + w′B, which vector detects w s-a-0?',opts:['A B C = 1 1 0','A B C = 1 1 1','A B C = 0 1 0'],correct:0,why:'110 activates w = 1 and sets B ⊕ C = 1. The good output is 0 and the faulty output is 1.'}];
const slides=[
{chapter:0,section:'BOOT SEQUENCE',name:'CATAPULT',source:'Both supplied lectures, opening slides',notes:'Introduce CATAPULT as a symbolic ATPG method for combinational circuits. The acronym expands to Concurrent Automatic Testing Allowing Parallelization and Using Limited Topology. This deck combines the algorithm explanation from the first lecture with the examples and limits from the second. The interactive circuits are educational examples, not an implementation of the complete CATAPULT engine.',render:()=>`<div class="hero"><div class="hero-copy"><div class="hero-top">${eyebrow('Digital circuits. Real detective work.')}<span class="edition">COE529</span></div><h1>CATA<span class="accent">PULT</span></h1><div class="hero-sub">THE LOGIC BEHIND THE TEST</div><p class="subtitle">Flip a bit. Follow a signal.<br>Find the fault hiding in the circuit.</p><div class="hero-bottom"><button class="start" data-go="1"><span class="play-icon">▶</span> Let’s explore</button><span class="hero-description">An interactive journey through symbolic test generation</span></div><div class="hero-label">Concurrent Automatic Testing Allowing<br>Parallelization and Using Limited Topology</div></div><div class="hero-visual"><div class="orb"></div><svg class="chip-board" viewBox="0 0 500 420" role="img" aria-label="Animated logic chip turns input 110 into a detecting test"><defs><linearGradient id="board" x2="1" y2="1"><stop stop-color="#a88af7"/><stop offset="1" stop-color="#7049d6"/></linearGradient><linearGradient id="core" x2="0" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#f2edff"/></linearGradient></defs><path fill="#6540b9" d="M100 90H400V333Q400 352 380 352H120Q100 352 100 332Z"/><rect x="100" y="70" width="300" height="265" rx="26" fill="url(#board)"/><path d="M120 70H380" stroke="#d4c1ff" stroke-width="3"/><g fill="#e1d9f8" stroke="#bdb0dd"><rect x="77" y="122" width="35" height="17" rx="4"/><rect x="77" y="177" width="35" height="17" rx="4"/><rect x="77" y="232" width="35" height="17" rx="4"/><rect x="388" y="122" width="35" height="17" rx="4"/><rect x="388" y="177" width="35" height="17" rx="4"/><rect x="388" y="232" width="35" height="17" rx="4"/><rect x="160" y="49" width="18" height="34" rx="4"/><rect x="241" y="49" width="18" height="34" rx="4"/><rect x="322" y="49" width="18" height="34" rx="4"/></g><g fill="none" stroke="#cfbbff" stroke-width="2"><path d="M112 130H145V175H185 M112 185H185 M112 240H145V215H185 M315 175H350V130H388 M315 195H388 M315 215H350V240H388"/></g><rect x="177" y="136" width="146" height="122" rx="18" fill="#5732a7"/><rect x="177" y="126" width="146" height="122" rx="18" fill="url(#core)" stroke="#c9b6f5" stroke-width="2"/><text x="250" y="174" text-anchor="middle" font-size="15" fill="#7b67a7">TEST ENGINE</text><text x="250" y="211" text-anchor="middle" font-size="31" fill="#6945e8">T(X)</text><text x="250" y="300" text-anchor="middle" font-size="12" fill="#f1eaff">BOOLEAN LOGIC / BDD CORE</text><circle class="signal-packet" r="5"><animateMotion dur="2.8s" repeatCount="indefinite" path="M77 130H145V175H185"/></circle><circle class="signal-packet" r="5"><animateMotion dur="2.8s" begin=".8s" repeatCount="indefinite" path="M77 185H185"/></circle><circle class="signal-packet" r="5"><animateMotion dur="2.8s" begin="1.4s" repeatCount="indefinite" path="M315 195H423"/></circle><text class="chip-bit" x="49" y="139" font-size="18" fill="#6945e8">1</text><text class="chip-bit" x="49" y="194" font-size="18" fill="#6945e8">1</text><text x="49" y="249" font-size="18" fill="#9e94b7">0</text><text x="440" y="202" font-size="18" fill="#6945e8">1</text></svg><div class="float-tag test-tag"><span class="tag-dot">✓ FAULT DETECTED</span><strong>test = 110</strong></div><div class="float-tag input-tag"><span class="tiny">INPUTS IN. ANSWERS OUT.</span><strong>3 inputs. 8 vectors.</strong></div></div></div>`},
{chapter:0,section:'BOOT SEQUENCE',name:'Lecture map',source:'Lecture 1, slides 2–3; Lecture 2, slide 2',notes:'The story has five parts. First define what it means to detect a stuck-at fault. Then build the algebraic tools, explain the CATAPULT workflow, verify a test on a live example, and discuss the method’s limits. Plan approximately 20–25 minutes including the demos and questions.',render:()=>layout(title('TODAY’S PROGRAM','Inside the<br><span class="accent">test generator</span>','One circuit. One target fault.<br>A function describing every valid test.')+'<p class="micro">26 SLIDES / LIVE LOGIC / SPEAKER NOTES</p>',`<div class="rows">${[['01','The testing problem','Activation, propagation and hard faults'],['02','The symbolic toolkit','Boolean difference and decision diagrams'],['03','The CATAPULT workflow','Decomposition, controllability and composition'],['04','The live test lab','A detecting vector and a redundancy proof'],['05','Limits and perspective','Benchmarks, BDD growth and later approaches']].map(x=>row(...x)).join('')}</div>`)},
{chapter:1,section:'THE TESTING PROBLEM',name:'A stuck-at fault',source:'Lecture 2, slide 3; introductory AND-gate demo added',notes:'Use this simple AND gate first. The output g is stuck at 0. With A=B=1 the good output is 1 and faulty output is 0, so the fault is detected. Toggle either input to 0 and the outputs agree. A single stuck-at model assumes one faulty line at a time.',render:()=>{let g=state.a&state.b;return layout(title('01 / FAULT MODEL','A line that<br>cannot switch','A single stuck-at fault fixes one line at 0 or 1, regardless of its intended value.')+buttons(['A','B'])+'<p class="micro">DEMO TARGET / g stuck-at-0</p>',term('fault_model.sim',`<div class="formula small">g = A · B</div>${svg(`<path class="wire" d="M50 80H200 M50 150H200 M360 115H520"/><path class="gate" d="M200 50H290A65 65 0 0 1 290 180H200Z"/><text x="240" y="121">AND</text><text x="50" y="65">A=${state.a}</text><text x="50" y="136">B=${state.b}</text><text x="435" y="96">g=${g}</text>`,'0 0 600 220')}${readout(g,0,g)}`))}},
{chapter:1,section:'THE TESTING PROBLEM',name:'Activation and propagation',source:'Lecture 1, slide 5; Lecture 2, slides 3 and 6',notes:'A test must satisfy both conditions simultaneously. Activation alone is insufficient because a downstream controlling value can mask the effect. Detection means an observable difference at a primary output. For multiple outputs it is enough for at least one output to differ.',render:()=>layout(title('TWO CONDITIONS','A fault becomes<br><span class="accent">observable</span>')+`<div class="rows">${row('01','Activation','Set the good fault site to the opposite of the stuck value.')}${row('02','Propagation','Make the resulting difference reach a primary output.')}</div>`,`${eyebrow('THE TEST CRITERION')}<div class="formula-stack">${formula('OUTPUT COMPARISON','F(X) ⊕ F<sub>fault</sub>(X) = 1')}${formula('COMPLETE TEST CONDITION','T = Activation · Propagation')}</div><p class="callout">A vector is a test only when both conditions hold for the same primary inputs.</p>`)},
{chapter:1,section:'THE TESTING PROBLEM',name:'Why symbolic ATPG?',source:'Lecture 1, slides 6–9; Lecture 2, slide 4',notes:'Structural approaches such as the D-algorithm, PODEM and FAN use decisions, implications and backtracking. Many faults are easy for these methods. The original CATAPULT abstract describes a back-end role for hard and redundant faults left by random or heuristic generators. Avoid suggesting the algorithm is always faster or replaces every structural method.',render:()=>layout(title('THE MOTIVATION','Hard faults make<br>search expensive','CATAPULT stores and manipulates Boolean functions to reuse computed information.')+`<div class="rows">${row('01','Structural ATPG','Decide, propagate and backtrack when constraints conflict.')}${row('02','CATAPULT’s role','Resolve hard faults and identify redundant faults after faster generators.')}</div>`,term('atpg_pipeline.log','<p class="muted">$ run random_and_heuristic_atpg</p><p>easy faults ................ detected</p><p class="amber">hard faults ................ remaining</p><p class="amber">redundant faults ........... unresolved</p><br><p class="prompt">$ handoff --engine CATAPULT</p><p>build symbolic test function T(X)</p><div class="result">return test vector / redundancy proof</div>'))},
{chapter:2,section:'THE SYMBOLIC TOOLKIT',name:'Boolean difference',source:'Lecture 1, slides 17–19; Lecture 2, slide 6',notes:'The Boolean difference is the XOR of two cofactors. Force the free fault-site variable to 0 and to 1, then compare the outputs. In the worked circuit F=wC+w′B, these cofactors are B and C. Toggle B and C to show that the difference is 1 only when they differ. This operation identifies propagation conditions, not activation.',render:()=>layout(title('02 / BOOLEAN DIFFERENCE','What happens if<br>the fault site flips?')+`<div class="formula small">∂F/∂g = F|<sub>g=0</sub> ⊕ F|<sub>g=1</sub></div><p class="flat-note">The result is 1 exactly when changing g changes the output.</p><p class="callout">For F = wC + w′B, the two cofactors are B and C.</p>`,term('cofactor_explorer.live',`${buttons(['B','C'])}<div class="code-row"><span>F|w=0 = B</span><span class="signal">${state.b}</span></div><div class="code-row"><span>F|w=1 = C</span><span class="signal">${state.c}</span></div><div class="result formula small">∂F/∂w = B ⊕ C = ${state.b^state.c}</div><p class="micro">${state.b^state.c?'PROPAGATION ENABLED':'FAULT EFFECT MASKED'}</p>`))},
{chapter:2,section:'THE SYMBOLIC TOOLKIT',name:'Binary decision diagrams',source:'Lecture 1, slide 10; Lecture 2, slides 7–8; test BDD from lecture 2, slide 12',notes:'Every node tests a variable. Dashed edges mean 0 and solid edges mean 1. This reduced ordered BDD represents T=ABC′. Toggle the inputs and follow the highlighted route. The only accepting assignment is 110. Fixed variable order plus the reduction rules gives a canonical representation. The graph can skip variables, which then become don’t-cares on that path.',render:()=>layout(title('BINARY DECISION DIAGRAMS','A Boolean function.<br><span class="accent">A graph of choices.</span>','Each path to terminal 1 describes a test cube. Skipped inputs are don’t-cares.')+'<div class="formula small">T = A · B · C′</div>'+buttons()+`<div class="legend"><span><i></i>input = 1</span><span><i class="dash"></i>input = 0</span></div>`,bdd()+`<p class="micro">ORDER A, B, C / TERMINAL ${(state.a&state.b&(1-state.c))?'1: VALID TEST':'0: NOT A TEST'}</p>`)},
{chapter:2,section:'THE SYMBOLIC TOOLKIT',name:'Why reduced and ordered?',source:'Lecture 2, slides 7–8',notes:'Reduction merges equivalent subgraphs and removes a decision if both outgoing edges point to the same result. A fixed order gives one ROBDD for a given function. That makes an already constructed zero function easy to recognize. Building the BDD is still costly, and compactness is not guaranteed.',render:()=>layout(title('THE REPRESENTATION','Why BDDs fit<br>the problem')+`<div class="rows">${row('01','Ordered','Use the same variable order along every path.')}${row('02','Reduced','Merge identical subgraphs. Remove decisions with identical children.')}${row('03','Canonical for a fixed order','Equivalent functions have the same reduced ordered graph.')}</div>`,term('test_function.inspect','<div class="code-row"><span>test exists?</span><span class="accent">T ≠ 0</span></div><div class="code-row"><span>read one test</span><span class="accent">path to 1</span></div><div class="code-row"><span>redundant fault?</span><span class="accent">T ≡ 0</span></div><div class="code-row"><span>represented result</span><span>complete test set</span></div><p class="result">The cost lies in constructing the graph.</p>'))},
{chapter:3,section:'THE CATAPULT WORKFLOW',name:'Functional decomposition',source:'Lecture 1, slides 15–16; Lecture 2, slide 9 and worked circuit from slide 11',notes:'A fanout stem feeds more than one branch. Here w=AB feeds one AND gate directly and the other through an inverter. The branches reconverge. Treating w as an explicit intermediate variable allows smaller functions of primary inputs and stems. This diagram is the educational example from lecture 2, not the original paper’s circuit.',render:()=>layout(title('03 / LIMITED TOPOLOGY','Fanout stems as<br>named variables','Decompose the circuit at stems. Keep intermediate functions small before composing them.')+`<div class="formula-stack">${formula('STEM FUNCTION','w = A · B')}${formula('OUTPUT FUNCTION','F = wC + w′B')}</div>`,circuit()+'<p class="micro">w FEEDS TWO PATHS THAT RECONVERGE AT F</p>')},
{chapter:3,section:'THE CATAPULT WORKFLOW',name:'The algorithm',source:'Lecture 1, slides 13 and 16–22; Lecture 2, slide 10',notes:'Select each stage to explain the algorithm. CC denotes the switching function in this deck, consistent with the first lecture. Activation uses CC for s-a-0 and its complement for s-a-1. The lecture descriptions emphasize reuse in traversals. They do not imply the entire algorithm takes one linear pass or that BDD operations are constant time. Partial composition may explore alternative paths.',render:()=>layout(title('THE ALGORITHM','Five stages.<br>One test function.')+`<div class="step-list">${steps.map((s,i)=>`<button data-step="${i}" class="${state.step===i?'selected':''}"><span>0${i+1}</span>${s[0]}</button>`).join('')}</div>`,`<div class="step-detail"><div class="step-number">0${state.step+1}</div><h3>${steps[state.step][0]}</h3><p>${steps[state.step][1]}</p><div class="rule-box formula small">${steps[state.step][2]}</div></div>`)},
{chapter:3,section:'THE CATAPULT WORKFLOW',name:'Controllability',source:'Lecture 1, slides 15–16 and 25',notes:'Use the first lecture’s convention: CC(s) is the actual switching function at s, not a scalar SCOAP difficulty measure. Compute functions in dependency order. s1 depends on primary inputs, s2 may also depend on s1, and later stems may depend on earlier ones. Store these functions as BDDs for reuse.',render:()=>layout(title('STAGE 01 / CONTROLLABILITY','The function at<br>the fault site','Compute switching functions using primary inputs and previously defined fanout stems.')+'<p class="callout">Here CC(g) means the Boolean function at g. It is not a numeric testability score.</p>',`<div class="formula-stack">${formula('FIRST STEM','s₁ = f₁(X)')}${formula('NEXT STEM','s₂ = f₂(X, s₁)')}${formula('LATER STEM','sₘ = fₘ(X, s₁, …, sₘ₋₁)')}</div><div class="rule-box"><div class="formula small">s-a-0 activation: CC(g)<br>s-a-1 activation: CC(g)′</div></div>`)},
{chapter:3,section:'THE CATAPULT WORKFLOW',name:'Observability',source:'Lecture 1, slides 17–19 and 27–29',notes:'Work backward from later stems. To compute an earlier stem’s observability, remove dependence on later stems through substitution or Shannon-based composition and then differentiate. With multiple outputs, OR their Boolean differences because observing the fault at any one output is sufficient. Correlated branches must be handled consistently.',render:()=>layout(title('STAGE 02 / OBSERVABILITY','The condition that<br>exposes a change')+`<div class="rows">${row('01','Backward dependency order','Resolve later stems before differentiating with respect to an earlier one.')}${row('02','Multiple outputs','OR the per-output observability functions.')}</div>`,`<div class="formula-stack">${formula('ONE OUTPUT','CO(g) = F|g=0 ⊕ F|g=1')}${formula('MULTIPLE OUTPUTS','CO(g) = ⋁ⱼ ∂Fⱼ/∂g')}</div><p class="callout">Shannon expansion: F = s · F|s=1 + s′ · F|s=0</p>`)},
{chapter:3,section:'THE CATAPULT WORKFLOW',name:'Test diagrams',source:'Lecture 1, slides 20 and 30; Lecture 2, slides 6 and 10',notes:'The formulas differ only in the activation term. For stuck-at-0 drive the fault site to 1, so use CC. For stuck-at-1 drive it to 0, so complement CC. In both cases propagation is the same Boolean difference. These are Boolean operations on functions represented as BDDs.',render:()=>`${title('STAGE 03 / TEST DIAGRAMS','Activation <span class="accent">AND</span> observability')}<div class="layout"><div class="rule-box">${eyebrow('FAULT g STUCK-AT-0')}<div class="formula">T₀ = CC(g) · CO(g)</div><p class="flat-note">Drive g to 1, then expose its effect.</p></div><div class="rule-box">${eyebrow('FAULT g STUCK-AT-1')}<div class="formula">T₁ = CC(g)′ · CO(g)</div><p class="flat-note">Drive g to 0, then expose its effect.</p></div></div>`},
{chapter:3,section:'THE CATAPULT WORKFLOW',name:'Partial composition',source:'Lecture 1, slides 21–22 and 32; simple contradiction added for explanation',notes:'Stems treated as independent symbols can create apparently satisfiable paths that no real primary input can realize. Example: s=AB, with a candidate requiring s=1 and A=0, is inconsistent after substitution. A valid alternative requiring s=1 and C=0 resolves to ABC′. Expand relevant paths; a failed path is not a proof of redundancy unless the complete resolved test function is zero.',render:()=>layout(title('STAGE 04 / COMPOSITION','Only primary inputs<br>can drive the chip','Substitute each stem’s function. Reject paths that conflict with the actual circuit.')+'<p class="callout">A failed candidate path does not prove redundancy. Other paths may still survive.</p>',term('compose_stems.trace','<p class="muted">definition: s = A · B</p><br><p class="amber">candidate 01: s=1, A=0</p><p>substitute: A · B · A′</p><p style="color:var(--red)">result: 0 / contradiction</p><br><p class="accent">candidate 02: s=1, C=0</p><p>substitute: A · B · C′</p><div class="result">result: test vector 110</div>'))},
{chapter:4,section:'THE LIVE TEST LAB',name:'Circuit simulator',source:'Lecture 2, slides 11–12; interactive simulator added',notes:'Invite the audience to find a detecting vector. For w s-a-0, the only test is 110. For w s-a-1, the detecting vectors are 001, 010 and 101. Switch the fault model and input bits to compare the good and faulty outputs. Rows in the truth table are clickable. This is an exhaustive simulator of this three-input educational circuit, not a general ATPG engine.',render:()=>{const r=calc(state.a,state.b,state.c,state.fault);return `<div class="lab">`+layout(title('04 / LIVE FAULT INJECTION','Can you detect <br>the fault?')+`<div class="tabs"><button data-fault="0" class="${!state.fault?'selected':''}">w stuck-at-0</button><button data-fault="1" class="${state.fault?'selected':''}">w stuck-at-1</button></div>${buttons()}${circuit()}${readout(r.good,r.bad,r.detect)}`,`<div class="interactive-label">CLICK A ROW TO APPLY ITS INPUT VECTOR</div><table class="truth"><thead><tr><th>A</th><th>B</th><th>C</th><th>w</th><th>GOOD F</th><th>FAULTY F</th><th>TEST?</th></tr></thead><tbody>${Array.from({length:8},(_,i)=>{let a=i>>2,b=(i>>1)&1,c=i&1,r=calc(a,b,c,state.fault);return `<tr tabindex="0" role="button" aria-label="Apply inputs ${a}${b}${c}" data-vector="${i}" class="${a===state.a&&b===state.b&&c===state.c?'current':''}"><td>${a}</td><td>${b}</td><td>${c}</td><td>${r.w}</td><td>${r.good}</td><td>${r.bad}</td><td class="${r.detect?'test':''}">${r.detect?'YES':'—'}</td></tr>`}).join('')}</tbody></table><p class="micro">F = wC + w′B / w = AB<br>Educational example from the supplied lecture.</p>`,'wide')+'</div>'}},
{chapter:4,section:'THE LIVE TEST LAB',name:'Deriving vector 110',source:'Lecture 2, slides 11–12',notes:'For w stuck-at-0, activation is AB. Propagation is B XOR C. Since AB requires B=1, the XOR becomes C′. Thus T=ABC′. Simulate 110: w=1, good output C=0, faulty output B=1. These equations describe the complete test set for this educational example.',render:()=>layout(title('THE DERIVATION','The complete<br>test set is <span class="accent">110</span>')+`<div class="formula-stack">${formula('ACTIVATION','CC(w) = AB')}${formula('OBSERVABILITY','CO(w) = B ⊕ C')}${formula('TEST FUNCTION','T₀ = AB(B ⊕ C) = ABC′')}</div>`,`<div class="vector-bits"><div><small>A</small>1</div><div><small>B</small>1</div><div><small>C</small>0</div></div>${term('verify_vector_110','<div class="code-row"><span>good: w=1, F=C</span><span>0</span></div><div class="code-row"><span>faulty: w=0, F=B</span><span>1</span></div><p class="result">0 ⊕ 1 = 1 / FAULT DETECTED</p>')}`)},
{chapter:4,section:'THE LIVE TEST LAB',name:'Redundancy proof',source:'Lecture 2, slide 13; interactive exhaustive check added',notes:'The consensus circuit is F=AB+A′C+BC, with h=BC. The target is h stuck-at-0. Activation needs BC=1. But when B=C=1 the remaining terms AB+A′C become A+A′=1 and mask the fault. Thus BC(AB+A′C)′ is always 0. Toggle the inputs to see outputs always agree. This logical proof assumes the single stuck-at combinational model.',render:()=>{const {a,b,c}=state;const good=(a&b)|((1-a)&c)|(b&c),bad=(a&b)|((1-a)&c);return layout(title('REDUNDANT FAULT','Sometimes the<br>answer is <span class="accent">no test</span>')+`<div class="formula small">F = AB + A′C + h<br>h = BC / target: h s-a-0</div><p class="flat-note">When BC = 1, the other terms already force F = 1.</p>${buttons()}${readout(good,bad,good^bad)}`,`<div class="big-zero">0</div><div class="formula small" style="text-align:center">T = BC · (AB + A′C)′ ≡ 0</div><p class="callout">The test BDD collapses to terminal 0.<br>The target fault is redundant.</p>`) }},
{chapter:3,section:'FAULT SELECTION',name:'The checkpoint set',source:'Lecture 1, slides 11–12',notes:'The first lecture gives a checkpoint set containing both stuck-at values on primary inputs, fanout branches and XOR gate outputs. Keep the distinction between a fanout stem, which is useful for functional decomposition, and its branches, which are selected fault sites in the checkpoint set. The course version explicitly includes XOR outputs. This is a selected fault set, not a claim that all physical defects are captured.',render:()=>layout(title('FAULT SELECTION','The checkpoint set','The lecture selects both s-a-0 and s-a-1 faults at specific circuit locations.')+`<div class="rows">${row('01','Primary inputs','Direct access points to the combinational network.')}${row('02','Fanout branches','Separate branches can have different propagation conditions.')}${row('03','XOR outputs','Included explicitly in the lecture’s checkpoint set.')}</div>`,`${eyebrow('SUPPORTED GATE NETWORK')}<div class="formula small">BUFFER · NOT<br>AND · NAND<br>OR · NOR · XOR</div><p class="callout">A smaller selected fault set reduces the number of target faults. Fanout stems also serve as decomposition variables.</p>`)},
{chapter:5,section:'LIMITS AND PERSPECTIVE',name:'ATPG paradigms',source:'Lecture 2, slide 14',notes:'This is a high-level comparison. Structural ATPG normally returns a test vector from a successful search. A test-function BDD represents all satisfying vectors when fully expressed in primary inputs; partial composition can stop after obtaining one test. SAT normally returns one satisfying assignment. Every method can incur large worst-case cost. SAT does not need to materialize a canonical BDD.',render:()=>`${title('05 / COMPARISON','Where the difficulty lives')}<div class="table-scroll"><table class="comparison"><thead><tr><th></th><th>Structural ATPG</th><th class="focus">BDD-based ATPG</th><th>SAT-based ATPG</th></tr></thead><tbody><tr><td>REPRESENTATION</td><td>Gate netlist<br>and logic implications</td><td class="focus">Boolean functions<br>as reduced ordered BDDs</td><td>Boolean formula<br>as CNF clauses</td></tr><tr><td>FINDING A TEST</td><td>Decisions and backtracking</td><td class="focus">Graph operations<br>and composition</td><td>Satisfying assignment</td></tr><tr><td>REDUNDANCY</td><td>Complete search fails</td><td class="focus">Resolved T is constant 0</td><td>Formula is unsatisfiable</td></tr><tr><td>MAIN COST</td><td>Search and backtracks</td><td class="focus">BDD size and composition</td><td>Solver search time</td></tr></tbody></table></div>`},
{chapter:5,section:'LIMITS AND PERSPECTIVE',name:'BDD size limits',source:'Lecture 2, slide 15; growth plot is a labeled mathematical illustration',notes:'A BDD is not guaranteed to be compact. Variable order can greatly change graph size. For important multiplier functions, exponential lower bounds persist across all orders. The interactive bars illustrate 2^n only; they are neither measured CATAPULT performance nor published lower-bound values. We intentionally avoid turning those theoretical bounds into a claim about a benchmark implementation.',render:()=>layout(title('THE BOTTLENECK','The graph can<br>grow exponentially')+`<div class="rows">${row('01','Order matters','A different variable order may dramatically change the graph size.')}${row('02','Some functions remain hard','Multiplier results show that a good order cannot always prevent exponential growth.')}${row('03','Composition has a cost','Keeping stems separate delays expansion, but does not remove the final dependencies.')}</div>`,`<div class="interactive-label">ILLUSTRATION / EXPONENTIAL GROWTH 2ⁿ</div><div class="growth">${[4,8,12,16,20].map(n=>`<div style="height:${Math.max(1,Math.pow(2,n)/Math.pow(2,20)*100)}%"><span>${n}</span></div>`).join('')}</div><div class="growth-caption"><div class="range-label"><label for="growthRange">n = ${state.bits}</label><span>2ⁿ = ${Math.pow(2,state.bits).toLocaleString()}</span></div><input class="range" type="range" min="4" max="24" value="${state.bits}" id="growthRange" aria-label="Exponent n"><p class="micro">Illustrative mathematics only. Bars use a linear scale.<br>Not a CATAPULT benchmark or a specific BDD node count.</p></div>`)},
{chapter:5,section:'LIMITS AND PERSPECTIVE',name:'Reported lecture results',source:'Lecture 1, slide 34, original embedded tables',notes:'These are the original table images from the first lecture. The timing table shows c432, six fault-site entries, TOPS time 311 and CATAPULT time 11. The BDD table shows maximum 524 and average 141. The supplied table image does not show the timing unit or enough experimental context to generalize the speed ratio. Present them as historical reported results, not a modern benchmark. Do not invent hardware, units or fault coverage.',render:()=>layout(title('REPORTED RESULTS','The lecture’s<br>c432 experiment','Original tables preserved from the first lecture.')+`<div class="formula-stack">${formula('MAXIMUM BDD SIZE','524')}${formula('AVERAGE BDD SIZE','141')}</div><p class="micro">Historical reported figures. Timing units and full setup are not visible in the supplied table image.</p>`,`<div class="results-img"><img src="assets/timing.png" alt="Original timing table for c432: six fault entries, TOPS 311 and CATAPULT 11"></div><div class="results-img" style="max-width:380px"><img src="assets/bdd-size.png" alt="Original BDD size table for c432: maximum 524, average 141"></div><p class="source-tag">SOURCE / CATAPULT PPT 2.pptx, slide 34<br>These values do not establish a general performance guarantee.</p>`)},
{chapter:5,section:'LIMITS AND PERSPECTIVE',name:'Legacy',source:'Lecture 2, slide 16 and references',notes:'The second lecture places CATAPULT after Bryant’s canonical BDD algorithms and before TSUNAMI and SAT-based ATPG work. TSUNAMI combines algebraic processing with path-oriented ideas. Larrabee’s 1992 work solves test generation via Boolean satisfiability. Keep this a historical perspective, without claiming current product adoption or a measured comparison.',render:()=>`${title('HISTORICAL CONTEXT','The ideas that followed','CATAPULT combines Boolean difference, BDDs and decomposition at fanout stems.')}<div class="timeline">${[['1986','Bryant','Canonical BDDs and graph algorithms'],['1988','CATAPULT','Symbolic ATPG for hard and redundant faults'],['1991','TSUNAMI','Partial BDDs and path-oriented algebraic testing'],['1992','SAT-based ATPG','Test generation using Boolean satisfiability']].map((t,i)=>`<div class="time-item ${i===1?'special':''}"><strong class="${i===1?'accent':''}">${t[0]}</strong><h3>${t[1]}</h3><p>${t[2]}</p></div>`).join('')}</div><p class="callout" style="margin-top:6vh">Later approaches explored ways to limit BDD construction or solve the test formula using a different representation.</p>`},
{chapter:6,section:'KNOWLEDGE CHECK',name:'Test your understanding',source:'Questions derived from both supplied lectures',notes:'Use the quiz as an audience checkpoint. There are three questions: activation for s-a-1, meaning of terminal 0, and the detecting vector for w s-a-0. Answers remain visible when switching questions and can be reset. Ask for a vote before clicking an option.',render:()=>{const q=questions[state.quiz],ans=state.answers[state.quiz];return layout(title('KNOWLEDGE CHECK','Your turn at<br>the test bench')+`<div class="tabs">${questions.map((_,i)=>`<button data-question="${i}" class="${state.quiz===i?'selected':''}">Q${i+1}${state.answers[i]!==undefined?' ✓':''}</button>`).join('')}</div><p class="micro">DISCUSS THE ANSWER BEFORE REVEALING IT</p><button class="inline-action" data-reset-quiz>Reset answers</button>`,`<h3>${q.q}</h3><div class="quiz-options">${q.opts.map((o,i)=>`<button data-answer="${i}" class="${ans!==undefined&&(i===q.correct?'correct':i===ans?'incorrect':'')}"><span>0${i+1}</span>${o}</button>`).join('')}</div><p class="quiz-feedback">${ans===undefined?'':`${ans===q.correct?'Correct.':'Try the reasoning again.'} ${q.why}`}</p>`) }},
{chapter:6,section:'TAKEAWAYS',name:'What to remember',source:'Lecture 1, slides 20–22; Lecture 2, slide 17',notes:'Conclude with the four core ideas. The test function is activation AND propagation. A BDD represents that function and gives tests through paths to 1. Stems help decomposition but must be resolved consistently. BDD size remains the limiting cost. Remind the audience that the app’s demos exhaustively verify small teaching circuits, while CATAPULT is the algorithm discussed in the lectures.',render:()=>`${title('CORE IDEAS','What CATAPULT gives us')}<div class="takeaways">${[['01','A function for the tests','Activation AND observability describes every detecting input.'],['02','A graph for the function','A path to 1 yields a test. A resolved constant 0 proves redundancy.'],['03','A role for circuit structure','Fanout stems keep subfunctions separate until composition.'],['04','A clear limit','BDD size can grow exponentially, especially on difficult arithmetic functions.']].map(t=>`<div class="takeaway"><span>${t[0]}</span><h3>${t[1]}</h3><p>${t[2]}</p></div>`).join('')}</div>`},
{chapter:6,section:'SOURCE DESK',name:'Sources and scope',source:'Both supplied PowerPoint files, including lecture 2 reference slide',notes:'The supplied lectures are the source of this presentation. Lecture 1 supplies the checkpoint set, detailed forward/backward workflow, partial composition discussion and table images. Lecture 2 supplies the small worked examples, context, limitations and bibliography. Its notes say the algorithm step summary relies on the original paper abstract and a later thesis rather than a full-paper review. Preserve that distinction. No external references were independently verified for this app.',render:()=>`${title('SOURCE DESK','Based on your lectures')}<div class="layout" style="min-height:unset;align-items:start"><div class="source-list"><h3>Supplied material</h3><p><strong>CATAPULT PPT 2.pptx</strong><br>Algorithm, checkpoint set, controllability, observability, partial composition and reported c432 tables.</p><p><strong>CATAPULT_ATPG.pptx</strong><br>Background, worked examples, redundancy proof, BDD limits and historical comparison.</p><p class="callout">The live demos use the second lecture’s educational examples. They are not examples attributed to the original CATAPULT paper.</p></div><div class="source-list"><h3>Selected references cited in the lectures</h3><p><strong>Gaede, Ross, Mercer & Butler (1988)</strong><br>“CATAPULT: Concurrent Automatic Testing Allowing Parallelization and Using Limited Topology.” DAC, pp. 597–600.</p><p><strong>Bushnell & Agrawal (2000)</strong><br><em>Essentials of Electronic Testing</em>, Chapter 7.</p><p><strong>Bryant (1986, 1991)</strong><br>BDD algorithms and complexity of graph representations.</p><p><strong>Stanion & Bhattacharya (1991); Larrabee (1992)</strong><br>TSUNAMI and test generation using Boolean satisfiability.</p><p class="micro">Lecture 2 identifies its step summary as a synthesis of the paper abstract and Balcárek’s 2016 thesis. References are reproduced from the lectures, not independently reviewed here.</p></div></div>`},
{chapter:6,section:'END OF PROGRAM',name:'Questions and discussion',source:'Synthesis of both lectures',notes:'Open discussion. Suggested prompts: Why must stems be composed out? Does a failed path prove redundancy? Can a better variable order always fix BDD size? What changes for a stuck-at-1 target? Use the lecture map to revisit a demo. Press Home to return to the opening slide.',render:()=>`<div class="end">${eyebrow('END OF PROGRAM / DISCUSSION')}<h2>Any <span class="accent">questions_</span></h2><p class="subtitle">What makes a fault detectable?<br>What makes its test function expensive to build?</p><div class="end-bottom"><div><span class="formula-label">THE EQUATION TO REMEMBER</span><div class="formula">T = Activation · Observability</div></div><button class="start" data-go="14">Reopen the test lab</button></div></div>`}
];
let scanTimer=null;
function syncMotion(){
 document.body.classList.toggle('motion-off',!state.motion);
 $('#motion').setAttribute('aria-pressed',String(state.motion));
 $('#motion').title=state.motion?'Pause animations (M)':'Enable animations (M)';
 document.querySelectorAll('svg').forEach(s=>{if(state.motion)s.unpauseAnimations?.();else s.pauseAnimations?.();});
}
function toggleMotion(){state.motion=!state.motion;document.body.classList.add('motion-explicit');if(!state.motion)stopScan();syncMotion();}
function replaySlide(){const slide=$('#stage .slide');slide.classList.remove('entering');void slide.offsetWidth;slide.classList.add('entering');}
function decorateSlide(entering){
 document.querySelectorAll('.row,.takeaway,.time-item,.formula-stack>div').forEach((el,i)=>el.style.setProperty('--order',i%5));
 if(!entering)document.querySelectorAll('.readout b').forEach(el=>el.classList.add('signal-flash'));
 if(state.i===14){
  $('.lab .readout').insertAdjacentHTML('afterend',`<div class="lab-controls"><button class="action-small ${state.scanning?'running':''}" id="runInputs">${state.scanning?'Ⅱ Pause scan':'▶ Run all inputs'}</button><span class="run-status" aria-live="polite">${state.scanning?`Vector ${state.runAt+1} / 8`:'Try every combination'}</span></div>`);
  $('#runInputs').onclick=()=>state.scanning?stopScan():startScan();
 }
 if(state.i===15){
  const items=[...document.querySelectorAll('.formula-stack>div')];
  items.forEach((el,i)=>{el.classList.toggle('reveal-pending',i>=state.reveal);el.classList.toggle('reveal-ready',i===state.reveal-1);el.setAttribute('aria-hidden',String(i>=state.reveal));});
  $('.formula-stack').insertAdjacentHTML('afterend',`<div class="reveal-controls"><button class="action-small" id="revealNext">${state.reveal<3?'✦ Reveal next step':'↻ Start again'}</button><span class="reveal-count">${state.reveal} / 3 steps revealed</span></div>`);
  $('#revealNext').onclick=()=>{state.reveal=(state.reveal+1)%4;render();};
 }
 if(state.i===22){const score=Object.entries(state.answers).filter(([i,a])=>questions[i].correct===a).length;$('.inline-action').insertAdjacentHTML('beforebegin',`<div><span class="quiz-score">✦ ${score} / 3 correct</span></div>`);}
 syncMotion();
}
function applyScanVector(i){state.runAt=i;state.a=i>>2;state.b=(i>>1)&1;state.c=i&1;render();}
function startScan(){
 stopScan(false);state.scanning=true;state.motion=true;document.body.classList.add('motion-explicit');applyScanVector(0);
 scanTimer=setInterval(()=>{if(state.i!==14){stopScan(false);return;}if(state.runAt===7){stopScan();$('.run-status').textContent='Scan complete · 8 vectors';return;}applyScanVector(state.runAt+1);},1250);
}
function stopScan(update=true){clearInterval(scanTimer);scanTimer=null;const was=state.scanning;state.scanning=false;if(was&&update)render();}
function celebrate(){
 if(!state.motion)return;
 const layer=document.createElement('div');layer.className='celebration';layer.setAttribute('aria-hidden','true');
 layer.innerHTML=Array.from({length:28},(_,i)=>`<i class="confetti" style="--x:${30+(i*17)%45}%;--drift:${(i%2?1:-1)*(35+i*5)}px;--spin:${i*37}deg;--delay:${(i%6)*.025}s;--confetti-color:${['#6945e8','#ff925c','#76c9a9','#b59afa'][i%4]}"></i>`).join('');
 document.body.append(layer);setTimeout(()=>layer.remove(),1800);
}
$('#motion').onclick=toggleMotion;$('#replay').onclick=replaySlide;
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopScan();});

function render(preserveFocus=false){const entering=$('#stage .slide')?.dataset.index!==String(state.i);state.i=Math.min(Math.max(state.i,0),slides.length-1);const s=slides[state.i];const focus=preserveFocus?document.activeElement:null;const key=focus?.dataset?.bit;$('#stage').innerHTML=`<section class="slide ${entering?'entering':''}" data-index="${state.i}" aria-labelledby="slide-heading">${s.render()}</section>`;const heading=$('#stage h1, #stage h2');if(heading)heading.id='slide-heading';$('#chapterNum').textContent=String(s.chapter).padStart(2,'0');$('#chapterLabel').textContent=s.section;$('#counter').innerHTML=`${String(state.i+1).padStart(2,'0')} <span>/ ${slides.length}</span>`;$('#progress>div').style.width=`${(state.i+1)/slides.length*100}%`;$('#prev').disabled=state.i===0;$('#next').disabled=state.i===slides.length-1;$('#noteTitle').textContent=s.name;$('#noteText').textContent=s.notes;$('#noteSource').textContent='SOURCE / '+s.source;document.title=`${state.i+1}. ${s.name} — CATAPULT`;decorateSlide(entering);if(key)$(`[data-bit="${key}"]`)?.focus();}
function go(i){stopScan(false);document.documentElement.style.setProperty('--direction',i>=state.i?1:-1);state.i=Math.min(Math.max(i,0),slides.length-1);history.replaceState(null,'','#'+(state.i+1));render();$('#stage').scrollTop=0;$('#announcement').textContent=`Slide ${state.i+1} of ${slides.length}: ${slides[state.i].name}`;}
function showOverview(){stopScan(false);const d=$('#overlay');$('.modal-head .eyebrow').textContent='NAVIGATOR';$('.modal-head h2').textContent='Lecture map';$('#modalBody').innerHTML=`<div class="slide-grid">${slides.map((s,i)=>`<button data-go="${i}" class="${state.i===i?'current':''}"><small>${String(i+1).padStart(2,'0')} / ${e(s.section)}</small>${e(s.name)}</button>`).join('')}</div>`;d.showModal();}
function showHelp(){const d=$('#overlay');$('.modal-head .eyebrow').textContent='CONTROLS';$('.modal-head h2').textContent='Presentation shortcuts';$('#modalBody').innerHTML=[['Next slide','→ / Space / Page Down'],['Previous slide','← / Page Up'],['First / last slide','Home / End'],['Slide overview','O'],['Speaker notes','N'],['Fullscreen','F'],['Close overlay / notes','Esc'],['Replay this slide','R'],['Toggle animation','M'],['This help','?']].map(x=>`<div class="shortcut-row"><span>${x[0]}</span><kbd>${x[1]}</kbd></div>`).join('')+'<p class="micro">Use Run all inputs in the test lab to animate every input vector. Use Reveal next step on the derivation slide. On touch screens, use the navigation buttons. All demos support keyboard focus and Enter/Space. Speaker notes appear on this screen; close them before projecting.</p>';d.showModal();}
function toggleNotes(){const p=$('#notesPanel');p.hidden=!p.hidden;$('#notes').setAttribute('aria-pressed',String(!p.hidden));}
async function fullscreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{showHelp();}}
$('#home').onclick=()=>go(0);$('#prev').onclick=()=>go(state.i-1);$('#next').onclick=()=>go(state.i+1);$('#overview').onclick=showOverview;$('#help').onclick=showHelp;$('#notes').onclick=toggleNotes;$('#closeNotes').onclick=toggleNotes;$('#fullscreen').onclick=fullscreen;
document.addEventListener('click',ev=>{const t=ev.target.closest('button,[data-vector]');if(!t)return;if(t.hasAttribute('data-go')){go(+t.dataset.go);if($('#overlay').open)$('#overlay').close();}if(t.hasAttribute('data-close'))$('#overlay').close();if(t.dataset.bit){stopScan(false);state[t.dataset.bit]^=1;render(true);}if(t.hasAttribute('data-fault')){stopScan(false);state.fault=+t.dataset.fault;render();}if(t.hasAttribute('data-vector')){stopScan(false);const i=+t.dataset.vector;state.a=i>>2;state.b=(i>>1)&1;state.c=i&1;render();}if(t.hasAttribute('data-step')){state.step=+t.dataset.step;render();}if(t.hasAttribute('data-question')){state.quiz=+t.dataset.question;render();}if(t.hasAttribute('data-answer')){const fresh=state.answers[state.quiz]!==+t.dataset.answer;state.answers[state.quiz]=+t.dataset.answer;render();if(fresh&&+t.dataset.answer===questions[state.quiz].correct)celebrate();}if(t.hasAttribute('data-reset-quiz')){state.answers={};render();}});
document.addEventListener('input',ev=>{if(ev.target.id==='growthRange'){state.bits=+ev.target.value;$('.range-label label').textContent='n = '+state.bits;$('.range-label span').textContent='2ⁿ = '+Math.pow(2,state.bits).toLocaleString();}});
document.addEventListener('keydown',ev=>{if(ev.target.matches('[data-vector]')&&['Enter',' '].includes(ev.key)){ev.preventDefault();ev.target.click();return;}if(ev.key==='Escape'){$('#notesPanel').hidden=true;return;}if($('#overlay').open)return;if(ev.target.matches('input,select,textarea'))return;if(ev.key===' '&&ev.target.closest('button'))return;const k=ev.key.toLowerCase();if(['arrowright','pagedown',' '].includes(k)){ev.preventDefault();go(state.i+1);}else if(['arrowleft','pageup'].includes(k)){ev.preventDefault();go(state.i-1);}else if(k==='home'){ev.preventDefault();go(0);}else if(k==='end'){ev.preventDefault();go(slides.length-1);}else if(k==='o')showOverview();else if(k==='n')toggleNotes();else if(k==='f')fullscreen();else if(k==='r')replaySlide();else if(k==='m')toggleMotion();else if(k==='?')showHelp();});
window.addEventListener('hashchange',()=>{state.i=(parseInt(location.hash.slice(1))||1)-1;render();});
render();
